    const acc = document.getElementById(id);
    await acc.nextSlide();
  };
  const prevSlide = async (id) => {
    const acc = document.getElementById(id);
    await acc.prevSlide();
  };
  const setActivated = async (id) => {
    const acc = document.getElementById(id);
    await acc.setActivated(2);
  };
  const pauseAutoplay = async (id) => {
    const acc = document.getElementById(id);
    await acc.pauseAutoplay();
  };
  const runAutoplay = async (id) => {
