const TableSorting = () => {
  const [arrow, setArrow] = useState('');
  const [sortedColumn, setSortedColumn] = useState(null);
  const [sortDirection, setSortDirection] = useState(1);

  const toggleSort = (columnIndex) => {
    if (sortedColumn === columnIndex) {
      setSortDirection(-sortDirection);
      if (sortDirection === -1) {
        setArrow('asc');
      } else {
        setArrow('dsc');
      }
    } else {
      setSortedColumn(columnIndex);
      setSortDirection(1);
      if (sortDirection === -1) {
        setArrow('dsc');
      } else {
        setArrow('asc');
      }
    }
  };

  const sortedData =
    sortedColumn !== null
      ? [...DATA].sort((a, b) => {
          const valA = a[heading[sortedColumn]];
          const valB = b[heading[sortedColumn]];

          console.log(sortedColumn);

          if (valA < valB) return -sortDirection;
          if (valA > valB) return sortDirection;
          return 0;
        })
      : DATA;

  return (
    <bds-table>
      <bds-table-header>
        <bds-table-row>
          {heading.map((item, index) => {
            return (
              <bds-table-th
                onClick={() => toggleSort(index)}
                sortable={sortedColumn === index ? true : false}
                arrow={arrow}
                key={index}
              >
                {item}
              </bds-table-th>
            );
          })}
        </bds-table-row>
      </bds-table-header>
      <bds-table-body>
        {sortedData.map((row, index) => {
          console.log(sortedColumn);
          return (
            <bds-table-row key={index}>
              <bds-table-cell>
                <bds-typo variant="fs-14" bold={sortedColumn === 0 ? 'bold' : 'regular'}>
                  {row.id}
                </bds-typo>
              </bds-table-cell>
              <bds-table-cell>
                <bds-typo variant="fs-14" bold={sortedColumn === 1 ? 'bold' : 'regular'}>
                  {row.produto}
                </bds-typo>
              </bds-table-cell>
              <bds-table-cell>
                <bds-typo variant="fs-14" bold={sortedColumn === 2 ? 'bold' : 'regular'}>
                  {row.valor}
